"""Public aggregate retirement receipt, no private per-file list or prediction payload."""
from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.stvg_native_instance_common_v1 import read,sha,write
BASE=ROOT/'artifacts/storage_cleanup_20261017_decota_tuning_v1'
def main():
 from scripts.export_stvg_lite_batch001 import public_source_text
 from scripts.publish_stvg_soft_ep_v1 import verify_privacy
 a=read(ROOT/'artifacts/storage_cleanup_20261017_unused_v2/COMPLETION.json');b=read(BASE/'COMPLETION.json');assert a['status']==b['status']=='complete'
 assert b['predictions_and_metadata_preserved_exact'] and b['current_method_and_active_scopes_hashes_pass'];out=ROOT/'results/storage_retirement/2026-10-17';out.mkdir(parents=True,exist_ok=False)
 write(out/'UNUSED_DOWNLOADS_MODELS_CACHES.json',a);write(out/'LEGACY_DECOTA_TUNING_STATES.json',b)
 lines=['# Storage retirement, 2026-10-17','','Explicit human authorization to delete unused artifacts/downloaded datasets/model weights, then specifically old tuning and DECoTA material. No new inference, model update, GT evaluation, promotion or restored historical queue. This receipt describes storage availability, not scientific performance.','','| Batch | Original containers | Logical GiB retired | Actual available-space increase GiB |','|---|---:|---:|---:|',f"|Unused downloads, inactive weights, old Teacher cache|{a['count']}|{a['logical_bytes']/2**30:.3f}|{a['net_available_increase']/2**30:.3f}|",f"|Legacy DECoTA optimizer states and tuning feature views|{b['count']}|{b['removed_logical_bytes']/2**30:.3f}|{b['net_available_increase']/2**30:.3f}|",'','The first batch removes unused MeViS/SportsGrounding/VidOR-training/GroundingYouTube archive packages, inactive VideoChat-R1.5 weight shards, abandoned STCAT fragments and closed Native/paper Teacher native.npz encodings. Original source/official receipts and native-cache retirement markers remain. Current R1/DINO/TA-STVG/TubeDETR weights, original HC/Vid videos, current Source prefix, context images, Teacher responses, predictions and research reports remain. Deleted model/dataset packages require re-download; retired Teacher features require reconstruction.','','The second batch retires93156 old DECoTA baseline NPZ containers after copying every Before.npy, After.npy and metadata.npy byte-for-byte into private prediction capsules; only state_before.npy/state_after.npy are removed. It also retires1082 completed tuning H_cache containers after retaining prediction and all other fields except feature views, with tensor dtype/shape/value and nested field equality checks. All retained capsule hashes and archive members are independently read back before deleting any original container. The private archives and complete manifests stay local, excluded from public export. Original old parameter-update replays now require reconstruction; final predictions, scalar reports, negative findings and configs remain.','','Reported actual free-space change accounts for archive cost, hard links and concurrent file writes; logical bytes alone are not claimed as physically freed. Two open-FD/mmap checks, per-file identity/SHA checks, CURRENT/paper/active-scope hashes and archive ledger validation accompany the retirement. Old binary paths are unavailable and mapped to retained archive members in the private retirement manifest. No claim is made that original optimizer-state replay remains immediately available.']
 doc=ROOT/'docs/STORAGE_RETIREMENT_20261017.md';doc.write_text('\n'.join(lines)+'\n')
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 fig,ax=plt.subplots(figsize=(7,3.5));ax.barh(['Unused downloads/models/cache','Old DECoTA/tuning states'],[a['net_available_increase']/2**30,b['net_available_increase']/2**30]);ax.set_xlabel('Actual available-space increase (GiB)');fig.tight_layout();fig.savefig(out/'freed_space.png',dpi=140);plt.close(fig)
 for n in ['retire_unused_storage_20261017_v2.py','retire_legacy_decota_tuning_states_20261017.py','report_stvg_storage_retirement_20261017.py']:
  p=out/'code'/n;p.parent.mkdir(exist_ok=True);p.write_text(public_source_text((ROOT/'scripts'/n).read_bytes()))
 paths={str(p.relative_to(ROOT)) for p in out.rglob('*') if p.is_file()}|{str(doc.relative_to(ROOT))};verify_privacy(paths);write(BASE/'publication/storage/EXPORT_MANIFEST.json',dict(status='complete',count=0,scope='storage maintenance, no model experiment',paths=sorted(paths),files=[dict(path=p,sha256=sha(ROOT/p),bytes=(ROOT/p).stat().st_size) for p in sorted(paths)]));print('STORAGE_RETIREMENT_EXPORT_READY',len(paths))
if __name__=='__main__':main()
